mapper.select:
select
    ,
    m.name member_name,
    b.id book_id,
    b.title,
    b.author,
    b.isbn,
    b.cover_object_key,
    bc.barcode,
    bc.location,
    case when r.returned_at is null and r.due_at < #{now}
         then greatest(1, ceiling(timestampdiff(second, r.due_at, #{now}) / 86400.0))
         else r.overdue_days end current_overdue_days
from borrow_record r
join member m on m.id = r.member_id
join book_copy bc on bc.id = r.copy_id
join book b on b.id = bc.book_id

    and r.id = #{q.id}
    and r.member_id = #{q.memberId}
    and m.name like concat('%', #{q.memberName}, '%')
    and b.id = #{q.bookId}
    and b.title like concat('%', #{q.bookTitle}, '%')
    and b.isbn like concat('%', #{q.isbn}, '%')
    and bc.barcode like concat('%', #{q.copyBarcode}, '%')
    and r.status = #{q.status}
    and r.return_outcome = #{q.returnOutcome}
    and r.status in ('BORROWING', 'OVERDUE') and r.returned_at is null
    and r.status in ('BORROWING', 'OVERDUE') and r.returned_at is null and r.due_at < #{now}
    and r.borrowed_at >= #{q.borrowedFrom}
    and r.borrowed_at <= #{q.borrowedTo}
    and r.due_at >= #{q.dueFrom}
    and r.due_at <= #{q.dueTo}

order by r.id desc

select 
from borrow_record r
where r.id = #{id}

select count(*)
from borrow_record
where member_id = #{memberId}
  and status in ('BORROWING', 'OVERDUE')
  and returned_at is null
  and due_at < #{now}

mapper.update:
update borrow_record
set due_at = #{dueAt},
    renew_count = renew_count + 1,
    last_renewed_at = #{now},
    version = version + 1,
    updated_at = #{now}
where id = #{id}
  and status = 'BORROWING'
  and returned_at is null
  and due_at > #{now}
  and version = #{version}

update borrow_record
set status = 'OVERDUE', version = version + 1, updated_at = #{now}
where id = #{id} and status = 'BORROWING'
  and returned_at is null and due_at < #{now}
